import{_ as a,o as t,c as s,a0 as o}from"./chunks/framework.F8L2D_2n.js";const u=JSON.parse('{"title":"Request Editor","description":"","frontmatter":{},"headers":[],"relativePath":"tui/request-editor.md","filePath":"tui/request-editor.md"}'),n={name:"tui/request-editor.md"};function r(i,e,l,d,c,p){return t(),s("div",null,[...e[0]||(e[0]=[o(`<h1 id="request-editor" tabindex="-1">Request Editor <a class="header-anchor" href="#request-editor" aria-label="Permalink to &quot;Request Editor&quot;">​</a></h1><p>Open a request from the list to enter the editor. It shows the request details across six tabs.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes catppuccin-latte catppuccin-mocha vp-code" tabindex="0"><code><span class="line"><span>┌───────────────────────────────────────────┐</span></span>
<span class="line"><span>│ Method    Server URL    URI       [Send]  │</span></span>
<span class="line"><span>├───────────────────────────────────────────┤</span></span>
<span class="line"><span>│ [Doc] [Params] [Auth] [Header] [Body] [Tests] │</span></span>
<span class="line"><span>├───────────────────────────────────────────┤</span></span>
<span class="line"><span>│                                           │</span></span>
<span class="line"><span>│  Tab Content                              │</span></span>
<span class="line"><span>│                                           │</span></span>
<span class="line"><span>├───────────────────────────────────────────┤</span></span>
<span class="line"><span>│  Response Preview                         │</span></span>
<span class="line"><span>└───────────────────────────────────────────┘</span></span></code></pre></div><h2 id="top-controls" tabindex="-1">Top controls <a class="header-anchor" href="#top-controls" aria-label="Permalink to &quot;Top controls&quot;">​</a></h2><ul><li><strong>Method</strong> — select from GET, POST, PUT, PATCH, DELETE, OPTIONS, HEAD</li><li><strong>Server URL</strong> — picked from the spec&#39;s <code>servers</code> list</li><li><strong>URI</strong> — the endpoint path, with <code>&amp;#123;&amp;#123;env.X&amp;#125;&amp;#125;</code> support</li><li><strong>Send</strong> — press <code>Enter</code> on the Send button to execute the request</li></ul><h2 id="tabs" tabindex="-1">Tabs <a class="header-anchor" href="#tabs" aria-label="Permalink to &quot;Tabs&quot;">​</a></h2><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>A free-form <strong>Summary</strong> (single line) and <strong>Description</strong> (multi-line) for the operation. These are persisted back to the OpenAPI spec on save.</p><h3 id="params" tabindex="-1">Params <a class="header-anchor" href="#params" aria-label="Permalink to &quot;Params&quot;">​</a></h3><p>Two sub-sections:</p><ul><li><strong>Query parameters</strong> — key/value pairs sent as URL query string. Add with <code>n</code> + <code>q</code>.</li><li><strong>Path parameters</strong> — key/value pairs that replace <code>{param}</code> placeholders in the URI. Add with <code>n</code> + <code>p</code>.</li></ul><h3 id="authorize" tabindex="-1">Authorize <a class="header-anchor" href="#authorize" aria-label="Permalink to &quot;Authorize&quot;">​</a></h3><p>Configure authentication schemes extracted from the spec. Add a scheme with <code>n</code> + <code>a</code>, remove with <code>x</code> + <code>a</code>. Supports:</p><ul><li><strong>Basic</strong> — Username + Password</li><li><strong>Bearer</strong> — Token</li><li><strong>API Key</strong> — Key Name + Key Value + In (header/query)</li><li><strong>OAuth2</strong> — Client ID + Client Secret + Token URL</li></ul><h3 id="header" tabindex="-1">Header <a class="header-anchor" href="#header" aria-label="Permalink to &quot;Header&quot;">​</a></h3><p>Custom HTTP headers as key/value pairs. Add with <code>n</code> + <code>h</code>. Common headers like <code>Content-Type</code> are set automatically from the body type.</p><h3 id="body" tabindex="-1">Body <a class="header-anchor" href="#body" aria-label="Permalink to &quot;Body&quot;">​</a></h3><p>The request body textarea. Supports two content types:</p><ul><li><strong><code>application/json</code></strong> — format your JSON here</li><li><strong><code>text/plain</code></strong> — plain text</li></ul><p>Select the type from the dropdown.</p><h3 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h3><p>Planned feature for response assertions. Currently a placeholder.</p><h2 id="field-navigation" tabindex="-1">Field navigation <a class="header-anchor" href="#field-navigation" aria-label="Permalink to &quot;Field navigation&quot;">​</a></h2><ul><li><code>Tab</code> / <code>Shift+Tab</code> cycles through: Method → Server → URI → Send → Tabs → Response</li><li><code>Enter</code> inside a tab activates tab content (Blocker mode)</li><li><code>Esc</code> blurs tab content; a second <code>Esc</code> exits the tab back to field cycling</li><li>Within tab content (e.g., Params rows), Tab/Shift+Tab wraps cyclically</li></ul><h2 id="saving" tabindex="-1">Saving <a class="header-anchor" href="#saving" aria-label="Permalink to &quot;Saving&quot;">​</a></h2><ul><li><code>Ctrl+S</code> — saves changes back to the spec (Summary, Description, param definitions, body content type, auth schemes)</li><li><code>Ctrl+E</code> — saves the last response as an example in the spec</li><li>Runtime values (body content, header values, param values) are saved to session temp files</li></ul>`,27)])])}const m=a(n,[["render",r]]);export{u as __pageData,m as default};
